DROP VIEW IF EXISTS crmls.view_rubijevsky cascade;
CREATE OR REPLACE VIEW crmls.view_rubijevsky AS
  SELECT
   68::integer as area_id,
   vl.*,
   neigh_places.label as __geo_neigh
  FROM
    (SELECT * FROM crmls.view_property WHERE ST_Within(__geo_geom, ST_SetSRID(''::geometry,4326)) and (city in ('Banning', 'Carson', 'Fairmont', 'Inglewood', 'Laguna Beach', 'Lancaster', 'Lompoc', 'Long Beach', 'Outside Area (Inside Ca)', 'Pine Cove', 'Playa Vista', 'Redlands', 'Wilmington') is not true)) vl
    LEFT OUTER JOIN
      (
        SELECT * FROM
          (
            SELECT
              vl.mlsnum AS mlsnum,
              places.category as category,
              array_agg(places.label) AS label
            FROM
              (SELECT * FROM crmls.view_property WHERE ST_Within(__geo_geom, ST_SetSRID(''::geometry,4326)) and (city in ('Banning', 'Carson', 'Fairmont', 'Inglewood', 'Laguna Beach', 'Lancaster', 'Lompoc', 'Long Beach', 'Outside Area (Inside Ca)', 'Pine Cove', 'Playa Vista', 'Redlands', 'Wilmington') is not true)) vl
              JOIN (select * from crmls.places where area_id = 68) as places ON ST_Contains(ST_SETSRID(places.way, 4326), vl.__geo_geom) 
            GROUP BY mlsnum, category
          ) mls_places
        WHERE category = 'Neighborhood'
      )
    neigh_places ON neigh_places.mlsnum = vl.mlsnum
;
